/* Immersive Experience · 设计套件 — 43 tokens · 来源:design */
:root{
  --tile-pro-badge-size: 15px;
  --expanded-toolbar-band: 32px;
  --expanded-sidebar-mode-columns: 3;
  --expanded-sidebar-mode-width: 204px;
  --expanded-sidebar-mode-index: 0;
  --expanded-color-token-offset-x: -50%;
  --slider-progress: 0%;
  --expanded-sidebar-prompt-primary: rgba(255, 255, 255, .92);
  --expanded-sidebar-prompt-secondary: rgba(255, 255, 255, .7);
  --expanded-sidebar-prompt-muted: rgba(255, 255, 255, .54);
  --expanded-sidebar-prompt-surface: rgba(255, 255, 255, .05);
  --expanded-sidebar-prompt-surface-strong: rgba(255, 255, 255, .08);
  --expanded-sidebar-prompt-border: rgba(255, 255, 255, .05);
  --expanded-sidebar-prompt-border-strong: rgba(255, 255, 255, .1);
  --viewer-create-surface-bg: var(--expanded-sidebar-prompt-surface);
  --viewer-create-surface-border: var(--expanded-sidebar-prompt-border);
  --viewer-create-surface-hover-bg: var(--expanded-sidebar-prompt-surface-strong);
  --viewer-create-surface-hover-border: var(--expanded-sidebar-prompt-border-strong);
  --viewer-create-surface-active-bg: rgba(255, 255, 255, .09);
  --viewer-create-surface-active-border: rgba(255, 255, 255, .12);
  --expanded-sidebar-loading-surface: rgba(18, 22, 30, .92);
  --expanded-sidebar-loading-panel: rgba(255, 255, 255, .05);
  --expanded-sidebar-loading-base: rgba(255, 255, 255, .1);
  --expanded-sidebar-loading-strong: rgba(255, 255, 255, .16);
  --expanded-sidebar-loading-sheen: rgba(147, 197, 253, .18);
  --expanded-sidebar-loading-copy: rgba(226, 234, 245, .72);
  --expanded-sidebar-loading-glow: rgba(147, 197, 253, .12);
  --kit-bg: #1c1c1c;
  --grid-gap: 8px;
  --radius-md: 6px;
  --radius-sm: 4px;
  --tile-stroke: rgba(255, 255, 255, 0.08);
  --glass-border-gradient: linear-gradient(180deg, rgba(255, 255, 255, 0.16), rgba(255, 255, 255, 0.04));
  --kit-preview-w: 1280;
  --kit-preview-h: 720;
  --kit-preview-aspect: 1280 / 720;
  --expanded-spacing-measure-border: rgba(245, 245, 245, 0.08);
  --expanded-spacing-measure-grid-line: rgba(245, 245, 245, 0.12);
  --expanded-spacing-measure-surface: rgba(27, 29, 39, 0.42);
  --expanded-spacing-sample-grid-line: rgba(245, 245, 245, 0.14);
  --expanded-spacing-sample-guide-fill: rgba(2, 6, 23, 0.12);
  --expanded-spacing-sample-guide-line: rgba(245, 245, 245, 0.22);
  --expanded-spacing-sample-grid-columns: 6;
}
